func PostReadings(w http.ResponseWriter, req *http.Request) {
	body, err := io.ReadAll(io.LimitReader(req.Body, reading.MaxBodyBytes+1))
	status, code, message := checkRequest(req.Header.Get("Content-Type"), body, err)
	var kind reading.Kind
	if status == 0 {
		kind, err = reading.ValidateUpload(body)
		status, code, message = uploadError(err)
	}
	if status != 0 {
		writeJSON(w, status, map[string]any{"error": map[string]string{"code": code, "message": message}})
		return
	}

	id, err := newUUID()
	if err != nil {
		writeJSON(w, 503, errBody("staging_unavailable", "The reading could not be staged."))
		return
	}
	job := &reading.Job{ID: id, StagingKey: "raw/" + id + ".json"}
	if err := stage(req.Context(), job.StagingKey, body); err != nil {
		rlog.Error("staging write failed", "reading_id", id, "err", err)
		writeJSON(w, 503, errBody("staging_unavailable", "The reading could not be staged."))
		return
	}
	topic := speedJobs
	if kind == reading.LineVoltage {
		topic = lineVoltageJobs
	}
	if _, err := topic.Publish(req.Context(), job); err != nil {
		rlog.Error("publish failed", "reading_id", id, "staging_key", job.StagingKey, "err", err)
		writeJSON(w, 503, errBody("publishing_unavailable", "The reading was staged but could not be queued."))
		return
	}
	writeJSON(w, http.StatusAccepted, map[string]string{"id": id})
}

func GetReadings(w http.ResponseWriter, req *http.Request) {
	limit, fleetID, assetID, err := parseQuery(req)
	if err != nil {
		code, message := "invalid_limit", "The limit query parameter must be an integer."
		if errors.Is(err, errFilter) {
			code, message = "invalid_train_filter", "fleet_id and asset_id must be provided together and must not be empty."
		}
		writeJSON(w, 400, errBody(code, message))
		return
	}
	var items []reading.Processed
	for entry, err := range results.List(req.Context(), &objects.Query{}) {
		if err != nil {
			rlog.Error("list results failed", "err", err)
			writeJSON(w, 503, errBody("results_unavailable", "The processed readings could not be retrieved."))
			return
		}
		body, err := io.ReadAll(results.Download(req.Context(), entry.Name))
		if err != nil {
			rlog.Error("read result failed", "key", entry.Name, "err", err)
			writeJSON(w, 503, errBody("results_unavailable", "The processed readings could not be retrieved."))
			return
		}
		var item reading.Processed
		if json.Unmarshal(body, &item) != nil {
			continue // skip objects that are not processed records
		}
		items = append(items, item)
	}
	writeJSON(w, 200, map[string]any{"readings": Select(items, limit, fleetID, assetID)})
}

